function withShortcut(title: string, shortcut?: string): string {
  return shortcut ? `${title}（${shortcut}）` : title;
}

/**
 * Transport bar (GUI_UX_SPEC §9). Mounted only once audio exists; every
 * control stays disabled while a command's snapshot predicate is false.
 *
 * All actions dispatch through the command surface (§23) — the Space key,
 * this button and a future menu item are the same command, so enabled
 * state and Japanese labels can never disagree across surfaces.
 *
 * `live` mirrors the transport adapter's low-frequency snapshot (UI-020):
 * play/pause icon, the MM:SS.t position/duration readout and the rate
 * button reflect the real audio clock. When no media transport is live but
 * a score clock runs (dev score-only path, UI-030), `timeLabel` supplies
 * the same readout; otherwise the static placeholder shows.
 */
export function TransportBar({
  commands,
  live,
  onCycleRate,
  timeLabel,
  followEnabled,
  followSuspended,
  onToggleFollow,
  auditionEnabled,
}: {
  commands: CommandSurface;
  live?: {
    isPlaying: boolean;
    positionSec: number;
    durationSec: number;
    rate: number;
    /** 元音源ミュート状態(#72)。 */
    muted?: boolean;
  };
  /** 再生速度 button — cycles SUPPORTED_RATES when the transport is live. */
  onCycleRate?(): void;
  /** [UI-030] "mm:ss.t / mm:ss.t" readout from the score clock when the
   *  media transport has no loaded source (score-only playback). */
  timeLabel?: string;
  /** [UI-030] 再生位置追従 armed state (§11); undefined = no score clock. */
  followEnabled?: boolean;
  /** [UI-030] Manual scroll suspended follow — button resumes it. */
  followSuspended?: boolean;
  onToggleFollow?(): void;
  /** FEAT-001 (#60): 楽譜の自動演奏がオンか(score clock がある時のみ)。 */
  auditionEnabled?: boolean;
}) {
  // All transport commands share the hasAudio gate (see definitions).
  const enabled = commands.isEnabled("transport.playPause");
  const position = live
    ? formatTimecode(live.positionSec)
    : (timeLabel?.split(" / ")[0] ?? ja.time.zero);
  const duration = live
    ? formatTimecode(live.durationSec)
    : (timeLabel?.split(" / ")[1] ?? ja.time.zeroTotal);
  const rateLabel = live ? `${live.rate}×` : "1.0×";
  return (
    <Toolbar
      className="hs-transport"
      aria-label={ja.transport.regionLabel}
      data-hs-focus-zone="transport"
      tabIndex={-1}
    >
      <Tooltip
        content={withShortcut(
          commands.title("transport.seekStart"),
          commands.shortcutLabel("transport.seekStart"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Previous24Regular />}
          aria-label={commands.title("transport.seekStart")}
          aria-keyshortcuts="Home"
          disabled={!commands.isEnabled("transport.seekStart")}
          onClick={() => commands.invoke("transport.seekStart")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.jumpBack"),
          commands.shortcutLabel("transport.jumpBack"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Rewind24Regular />}
          aria-label={commands.title("transport.jumpBack")}
          aria-keyshortcuts="J"
          disabled={!commands.isEnabled("transport.jumpBack")}
          onClick={() => commands.invoke("transport.jumpBack")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.playPause"),
          commands.shortcutLabel("transport.playPause"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={live?.isPlaying ? <Pause24Regular /> : <Play24Regular />}
          aria-label={
            live?.isPlaying ? ja.transport.pause : ja.transport.play
          }
          aria-keyshortcuts="Space K"
          disabled={!commands.isEnabled("transport.playPause")}
          appearance="primary"
          onClick={() => commands.invoke("transport.playPause")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.stop"),
          commands.shortcutLabel("transport.stop"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Stop24Regular />}
          aria-label={commands.title("transport.stop")}
          aria-keyshortcuts="Shift+Space"
          disabled={!commands.isEnabled("transport.stop")}
          onClick={() => commands.invoke("transport.stop")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.jumpForward"),
          commands.shortcutLabel("transport.jumpForward"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<FastForward24Regular />}
          aria-label={commands.title("transport.jumpForward")}
          aria-keyshortcuts="L"
          disabled={!commands.isEnabled("transport.jumpForward")}
          onClick={() => commands.invoke("transport.jumpForward")}
        />
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.seekEnd"),
          commands.shortcutLabel("transport.seekEnd"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<Next24Regular />}
          aria-label={commands.title("transport.seekEnd")}
          aria-keyshortcuts="End"
          disabled={!commands.isEnabled("transport.seekEnd")}
          onClick={() => commands.invoke("transport.seekEnd")}
        />
      </Tooltip>
      <span className="hs-transport__time" aria-label={ja.transport.position}>
        {position} / {duration}
      </span>

      <span className="hs-transport__spacer" />

      <Tooltip
        content={`${ja.transport.rate} ${rateLabel}`}
        relationship="label"
      >
        <ToolbarButton
          aria-label={`${ja.transport.rate} ${rateLabel}`}
          disabled={!enabled}
          onClick={onCycleRate}
        >
          {rateLabel}
        </ToolbarButton>
      </Tooltip>
      <Tooltip
        content={withShortcut(
          commands.title("transport.toggleLoop"),
          commands.shortcutLabel("transport.toggleLoop"),
        )}
        relationship="label"
      >
        <ToolbarButton
          icon={<ArrowRepeatAll24Regular />}
          aria-label={commands.title("transport.toggleLoop")}
          aria-keyshortcuts="Control+L"
          disabled={!commands.isEnabled("transport.toggleLoop")}
          onClick={() => commands.invoke("transport.toggleLoop")}
        />
      </Tooltip>
      <Tooltip
        content={
          followSuspended ? ja.scoreView.resumeFollow : ja.transport.follow
        }
        relationship="label"
      >
        <ToolbarButton
          icon={<SlideTextSparkle24Regular />}
          aria-label={
            followSuspended ? ja.scoreView.resumeFollow : ja.transport.follow
          }
          aria-pressed={followEnabled === true && !followSuspended}
          disabled={!enabled}
          onClick={onToggleFollow}
        />
      </Tooltip>
      {/* FEAT-001: 楽譜の自動演奏。スコアがある時だけ有効。 */}
      <Tooltip
        content={
          auditionEnabled ? ja.transport.auditionOn : ja.transport.auditionOff
        }
        relationship="label"
      >
        <ToolbarButton
          icon={<MusicNote2PlayRegular />}
          aria-label={
            auditionEnabled
              ? ja.transport.auditionOn
              : ja.transport.auditionOff
          }
          aria-pressed={auditionEnabled === true}
          disabled={!commands.isEnabled("transport.toggleAudition")}
          onClick={() => commands.invoke("transport.toggleAudition")}
        />
      </Tooltip>
      {/* #72: 元音源のミュート — 楽譜の演奏だけを聴く用途。 */}
      <Tooltip
        content={
          live?.muted ? ja.transport.unmuteSource : ja.transport.muteSource
        }
        relationship="label"
      >
        <ToolbarButton
          icon={live?.muted ? <SpeakerMute24Regular /> : <Speaker224Regular />}
          aria-label={
            live?.muted ? ja.transport.unmuteSource : ja.transport.muteSource
          }
          aria-pressed={live?.muted === true}
          disabled={!commands.isEnabled("transport.toggleSourceMute")}
          onClick={() => commands.invoke("transport.toggleSourceMute")}
        />
      </Tooltip>
    </Toolbar>
  );
}

import { useMemo } from "react";
import { ja } from "../strings/ja";
import { resizeKeyDelta, startPointerResize } from "../workspace/layout";
import type { LoadedAudio } from "../import/types";
import type { CaptureState } from "../capture/controller";
import { formatTimecode } from "../import/format";

/** Peak-column path for the strip: one <path> keeps redraw cost flat —
 *  vertical bars centred on the midline (the UI-004 wavesurfer adapter
 *  lands later; peaks geometry is already the real decoded audio). */
function peaksPath(peaks: readonly number[]): string {
  let d = "";
  for (let i = 0; i < peaks.length; i++) {
    const p = Math.min(1, Math.max(0, peaks[i]));
    d += `M${i + 0.5} ${50 - p * 48}L${i + 0.5} ${50 + p * 48}`;
  }
  return d;
}

/**
 * Waveform / timeline region (GUI_UX_SPEC §2, §8).
 * Height is user-resizable: 64px minimum up to ≈35% of the work area, and
 * always smaller than the score. The bottom-edge separator supports pointer
 * drag, ArrowUp/ArrowDown (±8px) and double-click reset — deterministic
 * clamps live in workspace/layout.ts.
 *
 * UI-020: renders decoded peaks + playhead once audio loads (§4), the
 * 波形を読み込んでいます line while OPENING_AUDIO, and click-to-seek
 * (§8) against the transport clock. Drag-select/zoom land with the real
 * waveform feature; the region stays honest about what exists.
 */
export function WaveformView({
  height,
  min,
  max,
  onResize,
  onReset,
  audio,
  loading = false,
  positionSec,
  onSeek,
  captureState,
}: {
  height: number;
  min: number;
  max: number;
  onResize(px: number): void;
  onReset(): void;
  /** Decoded audio (UI-020) — peaks render, null keeps the placeholder. */
  audio?: Pick<
    LoadedAudio,
    "fileName" | "durationSeconds" | "peaks"
  > | null;
  /** OPENING_AUDIO — honest loading line instead of fake peaks. */
  loading?: boolean;
  /** Audio-clock position for the playhead (seconds). */
  positionSec?: number;
  /** §8 click → seek: receives the target time in seconds. */
  onSeek?(seconds: number): void;
  /** FEAT-001 (#60): recording state — while a capture runs the strip
   *  shows the live recording status instead of a file's peaks. */
  captureState?: CaptureState | null;
}) {
  const path = useMemo(
    () => (audio ? peaksPath(audio.peaks) : ""),
    [audio],
  );
  const duration = audio?.durationSeconds ?? 0;
  const ratio =
    positionSec != null && duration > 0
      ? Math.min(1, Math.max(0, positionSec / duration))
      : null;
  return (
    <div
      className="hs-waveform"
      role="region"
      aria-label={ja.waveform.regionLabel}
      data-hs-focus-zone="waveform"
      tabIndex={0}
      style={{ height }}
      onClick={
        onSeek && duration > 0
          ? (e) => {
              const rect = e.currentTarget.getBoundingClientRect();
              const r = (e.clientX - rect.left) / Math.max(1, rect.width);
              onSeek(Math.min(1, Math.max(0, r)) * duration);
            }
          : undefined
      }
    >
      {loading ? (
        <span className="hs-waveform__placeholder">
          {ja.import.waveform.loading}
        </span>
      ) : captureState?.phase === "recording" ? (
        <span
          className="hs-waveform__recording"
          role="status"
          aria-live="polite"
        >
          {captureState.source === "loopback"
            ? ja.transport.recordingLoopbackLabel
            : ja.transport.recordingLabel}
          {" — "}
          {formatTimecode(captureState.elapsedSeconds)}
          {captureState.deviceName ? ` · ${captureState.deviceName}` : ""}
          {/* #71: 入力レベルの簡易メーター(0-1 のピーク)。 */}
          <span
            className="hs-waveform__level"
            aria-hidden="true"
          >
            <span
              className="hs-waveform__level-fill"
              style={{
                width: `${Math.round(
                  Math.min(1, Math.max(0, captureState.level ?? 0)) * 100,
                )}%`,
              }}
            />
          </span>
        </span>
      ) : audio ? (
        <>
          <svg
            className="hs-waveform__peaks"
            viewBox={`0 0 ${audio.peaks.length} 100`}
            preserveAspectRatio="none"
            aria-hidden="true"
          >
            <path d={path} />
          </svg>
          {ratio !== null ? (
            <div
              className="hs-waveform__playhead"
              style={{ left: `${ratio * 100}%` }}
              aria-hidden="true"
            />
          ) : null}
          <span className="hs-waveform__name" aria-hidden="true">
            {audio.fileName}
          </span>
        </>
      ) : (
        <span className="hs-waveform__placeholder">
          {ja.waveform.placeholder}
        </span>
      )}
      <div
        className="hs-waveform__resizer"
        role="separator"
        aria-orientation="horizontal"
        aria-label={ja.waveform.resizeHandle}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={height}
        tabIndex={0}
        onPointerDown={(e) => {
          const startH = height;
          const startY = e.clientY;
          startPointerResize(e, onResize, (_x, y) => startH + (y - startY));
        }}
        onClick={(e) => e.stopPropagation()}
        onKeyDown={(e) => {
          const next = resizeKeyDelta(e, height);
          if (next != null) {
            e.preventDefault();
            onResize(next);
          }
        }}
        onDoubleClick={onReset}
      />
    </div>
  );
}

/**
 * Import-owned score-region bodies (UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * ScoreWorkspace delegates the import-side machine states here:
 *   empty         → drop headline + 開く CTA + formats + trust + recents
 *   openingAudio  → honest indeterminate progress (§5: no fake %)
 *   audioReady    → file metadata + 採譜を開始 + 採譜オプション popover
 *   audioError    → copy-deck error card (別のファイルを選ぶ / 閉じる)
 *   sourceMissing → 元音源が見つかりません card (音源を指定 / 閉じる)
 *
 * All copy resolves through ja.import / ja.emptyState / ja.score — the
 * copy deck (protocol/copy/ja-JP.json) is the source of truth.
 */
import {
  ErrorCircle24Regular,
  FolderOpen24Regular,
  History24Regular,
  Play24Regular,
  Mic24Regular,
  Speaker2Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { HsButton } from "../components/primitives/Button";
import { HsNumericField } from "../components/primitives/NumericField";
import { HsPopover } from "../components/primitives/Popover";
import { HsProgress } from "../components/primitives/Progress";
import { HsSelect, type HsSelectOption } from "../components/primitives/Select";
import type { ScreenState } from "../workspace/screen";
import { formatBytes, formatDuration } from "./format";
import type {
  ImportIssue,
  LoadedAudio,
  RecentProjectEntry,
  SourceMissingInfo,
  TranscriptionOptions,
} from "./types";
import { issueText, type CaptureState } from "../capture/controller";

/** Everything the import-owned bodies need — assembled once in App and
 *  handed down through ScoreWorkspace (keeps that shared file's diff small
 *  for the sibling feature teams). */
export interface ImportView {
  audio: LoadedAudio | null;
  openingLabel: string | null;
  openingKind: "audio" | "project" | null;
  /** AUDIO_ERROR card content (no-audio failures). */
  issue: ImportIssue | null;
  /** SOURCE_MISSING context (project + last relink outcome). */
  sourceMissing: SourceMissingInfo | null;
  recentProjects: readonly RecentProjectEntry[];
  options: TranscriptionOptions;
  onOpenAudio(): void;
  onOpenProject(entry: RecentProjectEntry): void;
  onPickRelink(): void;
  onDismissError(): void;
  onOptionsChange(next: TranscriptionOptions): void;
  /** FEAT-001 (#60): capture controls on the EMPTY state. */
  captureState?: CaptureState | null;
  onStartCapture?(source: "loopback" | "microphone"): void;
}

/** Routes the import-owned screen states to their bodies. */
export function ImportScreenBody({
  screen,
  view,
  onTranscribe,
}: {
  screen: ScreenState;
  view: ImportView;
  onTranscribe(): void;
}) {
  switch (screen) {
    case "empty":
      return <EmptyStateBody view={view} />;
    case "openingAudio":
      return <OpeningAudioBody view={view} />;
    case "audioReady":
      return <AudioReadyBody view={view} onTranscribe={onTranscribe} />;
    case "audioError":
      return <AudioErrorBody view={view} />;
    case "sourceMissing":
      return <SourceMissingBody view={view} />;
    default:
      return null;
  }
}

