/**
 * Import flow controller (UI-020 / issue #25; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * Framework-free: App subscribes to state + screen events; tests drive it
 * with fake ports. The controller owns the §27 import-side transitions —
 *
 *   EMPTY ─pick/drop→ OPENING_AUDIO ─ok→ AUDIO_READY
 *                         ├─ unsupported/corrupt → AUDIO_ERROR ─閉じる→ EMPTY
 *                         └─ (audio already loaded: error surfaces as a
 *                             dialog issue over the kept workspace)
 *   recent project ─→ OPENING_AUDIO ─source ok→ AUDIO_READY
 *                         └─ path/hash failure → SOURCE_MISSING
 *                                └─ 音源を指定 → hash ok → AUDIO_READY
 *                                                mismatch → SOURCE_MISSING
 *
 * Error policy (§20): state what failed, what is kept, the next action —
 * a failed re-import never destroys a loaded audio session, and the source
 * file is only ever read (FND-001: identity = content hash, not location).
 */
import type { ScreenState } from "../workspace/screen";
import { ja } from "../strings/ja";
import { type ImportPorts } from "./ports";
import {
  audioFormatOf,
  baseName,
  projectDisplayName,
} from "./formats";
import {
  recordRecentProject,
  loadRecentProjects,
} from "./recentProjects";
import type {
  AudioFileRef,
  AudioFormat,
  ImportIssue,
  LoadedAudio,
  ProjectSummary,
  RecentProjectEntry,
  RecordedAudioRef,
  SourceMissingInfo,
} from "./types";

export type ImportPhase =
  | "idle"
  | "opening"
  | "ready"
  | "error"
  | "sourceMissing";

export interface ImportState {
  readonly phase: ImportPhase;
  /** File/project name shown while `phase === "opening"`. */
  readonly openingLabel: string | null;
  /** "audio" | "project" selects the loading copy variant. */
  readonly openingKind: "audio" | "project" | null;
  readonly audio: LoadedAudio | null;
  /** Recoverable failure — card content on AUDIO_ERROR, dialog content
      when the workspace already has audio (the error never destroys it). */
  readonly issue: ImportIssue | null;
  readonly sourceMissing: SourceMissingInfo | null;
}

export const INITIAL_IMPORT_STATE: ImportState = {
  phase: "idle",
  openingLabel: null,
  openingKind: null,
  audio: null,
  issue: null,
  sourceMissing: null,
};

export interface ImportEvents {
  /** Screen transitions owned by the import flow (§27). */
  onScreenChange(screen: ScreenState): void;
  /** Mirrors state for React consumers. */
  onState(state: ImportState): void;
  /** aria-live status bar announcements (role="status"). */
  announce(message: string): void;
  /** Recent-projects list changed (persisted + UI). */
  onRecentChange(entries: readonly RecentProjectEntry[]): void;
  /** Decoded audio is ready — host wires it into the transport adapter. */
  onAudioReady(audio: LoadedAudio): void;
}

type RecentStorage = Pick<Storage, "getItem" | "setItem"> | null;

export class ImportController {
  private state: ImportState = INITIAL_IMPORT_STATE;
  /** Serialization guard: a superseded open (user re-picked mid-load) must
      not overwrite newer state when it resolves late. */
  private generation = 0;

  constructor(
    private readonly ports: ImportPorts,
    private readonly events: ImportEvents,
    private readonly storage: RecentStorage = null,
  ) {}

  getState(): ImportState {
    return this.state;
  }

  /** `file.openAudio` (Ctrl+O / 開く / drop fallback): pick then import. */
  async openViaDialog(): Promise<void> {
    let ref: AudioFileRef | null;
    try {
      ref = await this.ports.pickAudio();
    } catch {
      // A picker failure is not a file error — surface the generic
      // open-failure issue rather than an unhandled rejection.
      this.fail({ kind: "openFailed" });
      return;
    }
    if (!ref) return; // cancel is silent — not an error
    await this.importRefs([ref]);
  }

  /**
   * Drag&drop / dialog entry point. With several files the first supported
   * one wins (single-document app); zero supported → honest format error.
   */
  async importRefs(refs: readonly AudioFileRef[]): Promise<void> {
    if (refs.length === 0) return;
    const ref = refs.find((r) => audioFormatOf(r.name) !== null) ?? refs[0];
    const format = audioFormatOf(ref.name);
    if (format === null) {
      this.fail({ kind: "unsupported", fileName: ref.name });
      return;
    }
    await this.importAudioRef(ref, format);
  }

  /**
   * FEAT-001 (#60): 録音バッファを直接取り込む(PC音源/マイク録音)。
   * `ref` は `kind:"recording"` で、`blob` は WAV または MediaRecorder
   * 出力(ブラウザ dev)。拡張子は常に `.wav`/`.webm` を仮定するため
   * `audioFormatOf` の allowlist を迂回して良い(録音由来なので形式は
   * 自明)。失敗時は openFailed に落とす。
   */
  async importRecording(ref: RecordedAudioRef): Promise<void> {
    const gen = this.begin("audio", ref.name);
    try {
      // Tauri 録音は保存済みファイルを読む(#70: 実ファイル=リリンク可能)。
      const blob = ref.blob ?? (await this.ports.readAudioBytes(ref.path!));
      const contentHash = ref.path
        ? await this.ports.sha256Hex(blob)
        : undefined;
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const audio: LoadedAudio = {
        ref: { ...ref, contentHash },
        fileName: ref.name,
        // 録音物は decode 可能なコンテナなので拡張子は実質 wav。
        format: "wav",
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.events.onAudioReady(audio);
      this.events.announce(
        ref.source === "loopback"
          ? `PCの音を取り込みました(${ref.name})`
          : `録音を取り込みました(${ref.name})`,
      );
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "openFailed", fileName: ref.name });
    }
  }

  /** OPENING_AUDIO → AUDIO_READY, or AUDIO_ERROR. */
  private async importAudioRef(
    ref: AudioFileRef,
    format: AudioFormat,
  ): Promise<void> {
    const gen = this.begin("audio", ref.name);
    try {
      const blob = await this.blobFor(ref);
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const audio: LoadedAudio = {
        ref,
        fileName: ref.name,
        format,
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.events.onAudioReady(audio);
      this.events.announce(ja.import.feedback.loaded(ref.name));
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "openFailed", fileName: ref.name });
    }
  }

  /**
   * 最近使ったプロジェクト → verify the recorded source path (store.py
   * `verify_source_audio`: exists + content hash) → AUDIO_READY, else
   * SOURCE_MISSING with the relink action.
   */
  async openProject(entry: RecentProjectEntry): Promise<void> {
    const gen = this.begin("project", entry.name);
    try {
      const bytes = await this.ports.readProjectBytes(entry.path);
      const project = parseProjectFile(await bytes.arrayBuffer(), entry.path);
      if (!this.isCurrent(gen)) return;
      if (!project.sourcePath || !project.sourceHash) {
        this.enterSourceMissing(project, false);
        return;
      }
      let blob: Blob;
      try {
        blob = await this.ports.readAudioBytes(project.sourcePath);
      } catch {
        if (!this.isCurrent(gen)) return;
        this.enterSourceMissing(project, false);
        return;
      }
      const hash = await this.ports.sha256Hex(blob);
      if (!this.isCurrent(gen)) return;
      if (hash !== project.sourceHash) {
        // File at the recorded path exists but content differs —
        // store.py treats this like a moved source (verify fails).
        this.enterSourceMissing(project, false);
        return;
      }
      try {
        const decoded = await this.ports.decodeAudio(blob, entry.name);
        if (!this.isCurrent(gen)) return;
        this.finishProjectOpen(
          project,
          {
            kind: "path",
            path: project.sourcePath,
            name: baseName(project.sourcePath),
          },
          blob,
          decoded,
        );
      } catch {
        if (!this.isCurrent(gen)) return;
        this.fail({
          kind: "openFailed",
          fileName: baseName(project.sourcePath),
        });
      }
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "projectOpenFailed", fileName: entry.name });
    }
  }

  /** SOURCE_MISSING: 「音源を指定」 — pick a candidate then verify. */
  async pickRelinkSource(): Promise<void> {
    let ref: AudioFileRef | null;
    try {
      ref = await this.ports.pickAudio();
    } catch {
      // Picker failure while relinking — stay on the SOURCE_MISSING card
      // and say what happened; the user can retry 音源を指定.
      this.events.announce(ja.import.errors.openFailedBody);
      return;
    }
    if (!ref) return;
    await this.relinkWith(ref);
  }

  /**
   * Hash-based relink, the same contract as
   * `ProjectStore.relink_source_audio`: the candidate must hash to the
   * recorded content hash — identity is content, not location.
   */
  async relinkWith(ref: AudioFileRef): Promise<void> {
    const sm = this.state.sourceMissing;
    if (!sm) return;
    const gen = this.begin("project", sm.project.name);
    try {
      const blob = await this.blobFor(ref);
      const hash = await this.ports.sha256Hex(blob);
      if (!this.isCurrent(gen)) return;
      if (hash !== sm.project.sourceHash) {
        this.enterSourceMissing(sm.project, true);
        return;
      }
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const format = audioFormatOf(ref.name) ?? "wav";
      const audio: LoadedAudio = {
        ref,
        fileName: ref.name,
        format,
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.touchRecent(sm.project);
      this.events.onAudioReady(audio);
      this.events.announce(ja.import.feedback.sourceRelinked);
    } catch {
      if (!this.isCurrent(gen)) return;
      // Candidate unreadable or undecodable after a hash match — stay on
      // the missing-source card; the status line carries what happened
      // (the card itself already offers the retry action).
      this.enterSourceMissing(sm.project, false);
      this.events.announce(ja.import.errors.openFailedBody);
    }
  }

  /** 閉じる on AUDIO_ERROR / SOURCE_MISSING → EMPTY; on a kept workspace
      (issue dialog over audio) it only clears the issue. */
  dismiss(): void {
    if (this.state.phase === "error" || this.state.phase === "sourceMissing") {
      this.setState({ ...INITIAL_IMPORT_STATE });
      return;
    }
    if (this.state.issue) {
      this.setState({ ...this.state, issue: null });
    }
  }

  /** Recent entries (host renders them in the EMPTY state). */
  recentProjects(): RecentProjectEntry[] {
    return loadRecentProjects(this.storage);
  }

  /* ----------------------------- internals ----------------------------- */

  private begin(kind: "audio" | "project", label: string): number {
    const gen = ++this.generation;
    this.setState({
      phase: "opening",
      openingLabel: label,
      openingKind: kind,
      audio: this.state.audio,
      issue: null,
      sourceMissing: null,
    });
    return gen;
  }

  private isCurrent(gen: number): boolean {
    return gen === this.generation;
  }

  private fail(issue: ImportIssue): void {
    if (this.state.audio) {
      // Workspace is alive — the issue becomes a dialog over it, the
      // loaded audio/waveform/transport all stay (§20 "what is kept").
      this.setState({ ...this.state, phase: "ready", issue });
    } else {
      this.setState({
        phase: "error",
        openingLabel: null,
        openingKind: null,
        audio: null,
        issue,
        sourceMissing: null,
      });
    }
  }

  private enterSourceMissing(
    project: ProjectSummary,
    mismatch: boolean,
  ): void {
    this.setState({
      phase: "sourceMissing",
      openingLabel: null,
      openingKind: null,
      audio: null,
      issue: null,
      sourceMissing: { project, mismatch },
    });
  }

  private finishProjectOpen(
    project: ProjectSummary,
    ref: AudioFileRef,
    blob: Blob,
    decoded: { durationSeconds: number; sampleRate: number; peaks: readonly number[] },
  ): void {
    const format = audioFormatOf(ref.name) ?? "wav";
    const audio: LoadedAudio = {
      ref,
      fileName: ref.name,
      format,
      sizeBytes: blob.size,
      durationSeconds: decoded.durationSeconds,
      sampleRate: decoded.sampleRate,
      peaks: decoded.peaks,
      mediaSource: { kind: "blob", blob },
    };
    this.setState({
      phase: "ready",
      openingLabel: null,
      openingKind: null,
      audio,
      issue: null,
      sourceMissing: null,
    });
    this.touchRecent(project);
    this.events.onAudioReady(audio);
    this.events.announce(ja.import.feedback.loaded(ref.name));
  }

  private touchRecent(project: ProjectSummary): void {
    const list = recordRecentProject(
      { name: project.name, path: project.path },
      this.storage,
    );
    this.events.onRecentChange(list);
  }

  private async blobFor(ref: AudioFileRef): Promise<Blob> {
    return ref.kind === "file" ? ref.file : this.ports.readAudioBytes(ref.path);
  }

  private setState(next: ImportState): void {
    this.state = next;
    this.events.onState(next);
    const screen = screenForPhase(next.phase);
    if (screen) this.events.onScreenChange(screen);
  }
}

/** The screen states the import flow drives; "ready" is the last one it
    owns — later transitions belong to the transcription/score features. */
function screenForPhase(phase: ImportPhase): ScreenState | null {
  switch (phase) {
    case "idle":
      return "empty";
    case "opening":
      return "openingAudio";
    case "ready":
      return "audioReady";
    case "error":
      return "audioError";
    case "sourceMissing":
      return "sourceMissing";
  }
}

/* --------------------------- project parsing --------------------------- */

/**
 * Parse a `.hornscribe.json` document into the relink-relevant summary
 * (schema v1 — mirrors `HornScribeProject.from_dict`). Throws on malformed
 * or unsupported documents → caller maps to `projectOpenFailed`.
 */
export function parseProjectFile(
  bytes: ArrayBuffer,
  path: string,
): ProjectSummary {
  const data = JSON.parse(new TextDecoder().decode(bytes)) as Record<
    string,
    unknown
  >;
  if (typeof data !== "object" || data === null) {
    throw new Error("project document is not an object");
  }
  if (data.schemaVersion !== 1) {
    throw new Error(`unsupported schemaVersion: ${String(data.schemaVersion)}`);
  }
  if (typeof data.projectId !== "string" || data.projectId === "") {
    throw new Error("projectId is missing or malformed");
  }
  const source = data.sourceAudio as Record<string, unknown> | null;
  return {
    path,
    projectId: data.projectId,
    name: projectDisplayName(path),
    sourcePath:
      source && typeof source.originalPath === "string"
        ? source.originalPath
        : null,
    sourceHash:
      source && typeof source.contentHash === "string"
        ? source.contentHash
        : null,
  };
}

/**
 * MediaElementTransport tests (UI-020 adapter over the UI-004 contract).
 * A FakePort stands in for HTMLAudioElement — the adapter's state machine,
 * snapshot emission and loop/seek/rate rules are what get asserted.
 */

import { describe, expect, it, vi } from "vitest";
import {
  MediaElementTransport,
  MIN_LOOP_SECONDS,
  type MediaPort,
  type MediaPortHandlers,
  type TransportSnapshot,
} from "./mediaTransport";
import type { MediaSource } from "./types";

class FakePort implements MediaPort {
  time = 0;
  duration = 120;
  rate = 1;
  preservePitch = true;
  playing = false;
  loaded: MediaSource | null = null;
  seekCalls: number[] = [];
  failLoad = false;
  private handlers = new Set<MediaPortHandlers>();

  async load(source: MediaSource): Promise<void> {
    if (this.failLoad) throw new Error("load failed");
    this.loaded = source;
  }
  async play(): Promise<void> {
    this.playing = true;
  }
  pause(): void {
    this.playing = false;
  }
  seekTo(seconds: number): void {
    this.time = seconds;
    this.seekCalls.push(seconds);
  }
  setRate(rate: number): void {
    this.rate = rate;
  }
  setPreservePitch(on: boolean): void {
    this.preservePitch = on;
  }
  muted = false;
  setMuted(on: boolean): void {
    this.muted = on;
  }
  getTime(): number {
    return this.time;
  }
  getDuration(): number {
    return this.duration;
  }
  subscribe(handlers: MediaPortHandlers): () => void {
    this.handlers.add(handlers);
    return () => this.handlers.delete(handlers);
  }
  emit(key: keyof MediaPortHandlers): void {
    for (const h of this.handlers) h[key]?.();
  }
}

function makeTransport(failLoad = false) {
  const port = new FakePort();
  port.failLoad = failLoad;
  const transport = new MediaElementTransport(port);
  const snaps: TransportSnapshot[] = [];
  transport.subscribe((s) => snaps.push(s));
  return { port, transport, snaps };
}

const SRC: MediaSource = { kind: "blob", blob: new Blob(["x"]) };

describe("load", () => {
  it("empty → loading → ready with snapshots on each step", async () => {
    const { transport, snaps } = makeTransport();
    await transport.load(SRC);
    expect(transport.getSnapshot().status).toBe("ready");
    expect(snaps.map((s) => s.status)).toEqual(["loading", "ready"]);
  });

  it("a failed load flips to error and rejects", async () => {
    const { transport, snaps } = makeTransport(true);
    await expect(transport.load(SRC)).rejects.toThrow();
    expect(transport.getSnapshot().status).toBe("error");
    expect(snaps.map((s) => s.status)).toEqual(["loading", "error"]);
  });
});

describe("play / pause / stop / ended", () => {
  it("play → playing; pause → paused; play after ended rewinds first", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    expect(transport.getSnapshot().status).toBe("playing");

    transport.pause();
    expect(transport.getSnapshot().status).toBe("paused");

    // `ended` only fires while playing (a paused element never ends).
    await transport.play();
    port.time = 42;
    port.emit("onEnded");
    expect(transport.getSnapshot().status).toBe("ended");

    await transport.play();
    expect(port.seekCalls.at(-1)).toBe(0); // rewind before replay
    expect(transport.getSnapshot().status).toBe("playing");
  });

  it("stop pauses and seeks to 0 (loop start when armed)", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    transport.setLoop({ start: 10, end: 20 });
    port.time = 15;
    transport.stop();
    expect(port.playing).toBe(false);
    expect(port.time).toBe(10);
    expect(transport.getSnapshot().status).toBe("ready");
  });

  it("no-ops while empty/loading (no source yet)", async () => {
    const { transport } = makeTransport();
    await transport.play(); // status empty — silently ignored
    transport.pause();
    transport.stop();
    expect(transport.getSnapshot().status).toBe("empty");
  });
});

describe("seek / rate / loop", () => {
  it("seek clamps into [0, duration] and unsticks 'ended'", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    port.emit("onEnded");
    await transport.seek(50);
    expect(port.time).toBe(50);
    expect(transport.getSnapshot().status).toBe("paused");
    await transport.seek(999);
    expect(port.time).toBe(120);
    await transport.seek(-3);
    expect(port.time).toBe(0);
  });

  it("setRate clamps to [0.25, 4] and emits", async () => {
    const { port, transport } = makeTransport();
    transport.setRate(2);
    expect(port.rate).toBe(2);
    transport.setRate(0.01);
    expect(port.rate).toBe(0.25);
    transport.setRate(99);
    expect(port.rate).toBe(4);
  });

  it("setLoop validates the range and clears on null", async () => {
    const { transport } = makeTransport();
    await transport.load(SRC);
    transport.setLoop({ start: 5, end: 5 + MIN_LOOP_SECONDS / 2 });
    expect(transport.getSnapshot().loop).toBeNull(); // too short → rejected
    transport.setLoop({ start: 5, end: 30 });
    expect(transport.getSnapshot().loop).toEqual({ start: 5, end: 30 });
    transport.setLoop(null);
    expect(transport.getSnapshot().loop).toBeNull();
  });

  it("playback past loop.end wraps to loop.start (A-B via media seek)", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    await transport.play();
    transport.setLoop({ start: 10, end: 20 });
    port.time = 20.5;
    port.emit("onTimeUpdate");
    expect(port.seekCalls.at(-1)).toBe(10);
  });

  it("load clears a previously armed loop", async () => {
    const { transport } = makeTransport();
    await transport.load(SRC);
    transport.setLoop({ start: 1, end: 2 });
    await transport.load(SRC);
    expect(transport.getSnapshot().loop).toBeNull();
  });
});

describe("snapshots / listeners", () => {
  it("revision bumps per emit; time mirrors the audio clock", async () => {
    const { port, transport, snaps } = makeTransport();
    await transport.load(SRC);
    port.time = 33;
    port.emit("onTimeUpdate");
    const last = snaps.at(-1)!;
    expect(last.time).toBe(33);
    expect(last.revision).toBe(snaps.length);
    expect(last.duration).toBe(120);
  });

  it("unsubscribe stops notifications; dispose pauses the port", async () => {
    const { port, transport } = makeTransport();
    await transport.load(SRC);
    const spy = vi.fn();
    const off = transport.subscribe(spy);
    transport.pause();
    transport.setRate(1.5);
    expect(spy).toHaveBeenCalled();
    off();
    const calls = spy.mock.calls.length;
    transport.setRate(1.25);
    expect(spy.mock.calls.length).toBe(calls);

    await transport.play();
    transport.dispose();
    expect(port.playing).toBe(false);
  });
});

/**
 * Minimal TransportController adapter for the AUDIO_READY state (UI-020),
 * consistent with the UI-004 spike contract
 * (apps/spikes/waveform/src/transport/types.ts).
 *
 * HornScribe owns this contract: the HTMLMediaElement is an adapter behind
 * `MediaPort`, the audio clock (`getCurrentTime`) is authoritative, and
 * snapshots are emitted to subscribers on state changes and media
 * timeupdate ticks (media-element cadence ≈4 Hz — no rAF, no 60 Hz
 * React churn; the full UI-004 pipeline with its rAF pump/Regions lands
 * with the real waveform view).
 *
 * A-B loop semantics mirror the spike: `[start, end)` wraps via a media
 * seek, which costs a small audible gap — the documented MediaElement
 * constraint, accepted here for the import-stage adapter.
 */
import type { MediaSource } from "./types";

export type TransportStatus =
  | "empty"
  | "loading"
  | "ready"
  | "playing"
  | "paused"
  | "ended"
  | "error";

/** Half-open time range in seconds: [start, end). */
export interface TimeRange {
  start: number;
  end: number;
}

export interface TransportSnapshot {
  status: TransportStatus;
  /** Audio-clock time in seconds (low-frequency mirror; use getCurrentTime
      for per-frame reads). */
  time: number;
  duration: number;
  rate: number;
  loop: TimeRange | null;
  /** 元音源のミュート(#72)。楽譜の演奏だけを聴く用途で使う。 */
  muted: boolean;
  /** Monotonic counter bumped on every emitted snapshot. */
  revision: number;
}

export type TransportListener = (snapshot: TransportSnapshot) => void;
export type Unsubscribe = () => void;

export const MIN_RATE = 0.25;
export const MAX_RATE = 4;
export const SUPPORTED_RATES = [0.5, 0.75, 1, 1.25, 1.5] as const;
/** Loops shorter than this are rejected (noise-level accidental drags). */
export const MIN_LOOP_SECONDS = 0.01;

/** Event feed the port must surface to the adapter. */
export interface MediaPortHandlers {
  onTimeUpdate?(): void;
  onEnded?(): void;
  onError?(): void;
}

/**
 * The media backend seam (UI-004 spike naming). `load` resolves when the
 * source is decoded enough to report a duration and accept play().
 */
export interface MediaPort {
  load(source: MediaSource): Promise<void>;
  play(): Promise<void>;
  pause(): void;
  seekTo(seconds: number): void;
  setRate(rate: number): void;
  setPreservePitch(on: boolean): void;
  setMuted(on: boolean): void;
  getTime(): number;
  getDuration(): number;
  subscribe(handlers: MediaPortHandlers): Unsubscribe;
}

/* ---------------------- HTMLAudioElement backend ---------------------- */

class AudioElementMediaPort implements MediaPort {
  private readonly el: HTMLAudioElement;
  private objectUrl: string | null = null;
  private readonly handlers = new Set<MediaPortHandlers>();

  constructor(el?: HTMLAudioElement) {
    this.el = el ?? new Audio();
    this.el.preload = "auto";
    this.el.addEventListener("timeupdate", () => this.emit("onTimeUpdate"));
    this.el.addEventListener("ended", () => this.emit("onEnded"));
    this.el.addEventListener("error", () => this.emit("onError"));
  }

  private emit(key: keyof MediaPortHandlers) {
    for (const h of this.handlers) h[key]?.();
  }

  load(source: MediaSource): Promise<void> {
    this.revoke();
    const url =
      source.kind === "url"
        ? source.url
        : ((this.objectUrl = URL.createObjectURL(source.blob)), this.objectUrl);
    return new Promise<void>((resolve, reject) => {
      const cleanup = () => {
        this.el.removeEventListener("loadedmetadata", ok);
        this.el.removeEventListener("error", ng);
      };
      const ok = () => {
        cleanup();
        resolve();
      };
      const ng = () => {
        cleanup();
        reject(new Error("media element could not load the source"));
      };
      this.el.addEventListener("loadedmetadata", ok, { once: true });
      this.el.addEventListener("error", ng, { once: true });
      this.el.src = url;
    });
  }

  private revoke() {
    if (this.objectUrl) {
      URL.revokeObjectURL(this.objectUrl);
      this.objectUrl = null;
    }
  }

  play(): Promise<void> {
    return this.el.play();
  }
  pause(): void {
    this.el.pause();
  }
  seekTo(seconds: number): void {
    this.el.currentTime = seconds;
  }
  setRate(rate: number): void {
    this.el.playbackRate = rate;
  }
  setPreservePitch(on: boolean): void {
    // Set the standard property plus the historical vendor-prefixed ones —
    // engines ignore the names they do not implement.
    const el = this.el as HTMLAudioElement & {
      mozPreservesPitch?: boolean;
      webkitPreservesPitch?: boolean;
    };
    el.preservesPitch = on;
    el.mozPreservesPitch = on;
    el.webkitPreservesPitch = on;
  }
  setMuted(on: boolean): void {
    this.el.muted = on;
  }
  getTime(): number {
    return this.el.currentTime;
  }
  getDuration(): number {
    return Number.isFinite(this.el.duration) ? this.el.duration : 0;
  }
  subscribe(handlers: MediaPortHandlers): Unsubscribe {
    this.handlers.add(handlers);
    return () => this.handlers.delete(handlers);
  }
}

/* ------------------------------ controller ------------------------------ */

export class MediaElementTransport {
  private readonly port: MediaPort;
  private status: TransportStatus = "empty";
  private rate = 1;
  private loop: TimeRange | null = null;
  private muted = false;
  private revision = 0;
  private readonly listeners = new Set<TransportListener>();

  constructor(port?: MediaPort) {
    this.port = port ?? new AudioElementMediaPort();
    this.port.subscribe({
      onTimeUpdate: () => {
        if (this.status === "playing" && this.loop) {
          const t = this.port.getTime();
          if (t >= this.loop.end) {
            // A-B wrap via media seek — see doc header for the known
            // ~60 ms MediaElement gap measured in the UI-004 spike.
            this.port.seekTo(this.loop.start);
          }
        }
        this.emit();
      },
      onEnded: () => {
        if (this.status === "playing") {
          this.status = "ended";
          this.emit();
        }
      },
      onError: () => {
        if (this.status !== "empty") {
          this.status = "error";
          this.emit();
        }
      },
    });
  }

  /** Load a source. Resolves when ready to play; rejects → status "error". */
  async load(source: MediaSource): Promise<void> {
    this.status = "loading";
    this.loop = null;
    this.emit();
    try {
      await this.port.load(source);
      this.status = "ready";
    } catch (e) {
      this.status = "error";
      this.emit();
      throw e;
    }
    this.emit();
  }

  async play(): Promise<void> {
    if (this.status === "empty" || this.status === "loading") return;
    if (this.status === "ended") this.port.seekTo(0);
    if (this.status === "playing") return;
    await this.port.play();
    this.status = "playing";
    this.emit();
  }

  pause(): void {
    if (this.status !== "playing") return;
    this.port.pause();
    this.status = "paused";
    this.emit();
  }

  /** Pause and return to t=0 (or the loop start when a loop is armed). */
  stop(): void {
    if (this.status === "empty" || this.status === "loading") return;
    this.port.pause();
    this.port.seekTo(this.loop?.start ?? 0);
    this.status = "ready";
    this.emit();
  }

  /** Seek to an absolute position in seconds, clamped to [0, duration]. */
  async seek(seconds: number): Promise<void> {
    const duration = this.port.getDuration();
    const target = Math.min(Math.max(seconds, 0), duration);
    this.port.seekTo(target);
    if (this.status === "ended") this.status = "paused";
    this.emit();
  }

  /** Playback rate, clamped to [MIN_RATE, MAX_RATE]. */
  setRate(rate: number): void {
    this.rate = Math.min(MAX_RATE, Math.max(MIN_RATE, rate));
    this.port.setRate(this.rate);
    this.emit();
  }

  /** Request pitch preservation for rate != 1 (backend permitting). */
  setPreservePitch(on: boolean): void {
    this.port.setPreservePitch(on);
    this.emit();
  }

  /** 元音源のミュート(#72)。ミュートはメディア要素側の属性なので、
      ループバック録音中でも録音対象の音は止まらない — モニターの
      聴こえ方だけを切る。 */
  setMuted(on: boolean): void {
    if (this.muted === on) return;
    this.muted = on;
    this.port.setMuted(on);
    this.emit();
  }

  /** Arm (TimeRange) or clear (null) the A-B loop. Degenerate/inverted
      ranges and ranges past the media end are rejected (clamped). */
  setLoop(range: TimeRange | null): void {
    if (range === null) {
      this.loop = null;
      this.emit();
      return;
    }
    const duration = this.port.getDuration();
    const start = Math.max(0, range.start);
    const end = Math.min(duration, range.end);
    if (end - start < MIN_LOOP_SECONDS) return;
    this.loop = { start, end };
    this.emit();
  }

  /** Authoritative audio-clock time — read on demand. */
  getCurrentTime(): number {
    return this.port.getTime();
  }
  getDuration(): number {
    return this.port.getDuration();
  }

  getSnapshot(): TransportSnapshot {
    return {
      status: this.status,
      time: this.port.getTime(),
      duration: this.port.getDuration(),
      rate: this.rate,
      loop: this.loop ? { ...this.loop } : null,
      muted: this.muted,
      revision: this.revision,
    };
  }

  subscribe(listener: TransportListener): Unsubscribe {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  dispose(): void {
    this.listeners.clear();
    this.port.pause();
  }

  private emit(): void {
    this.revision += 1;
    const snap = this.getSnapshot();
    for (const l of this.listeners) l(snap);
  }
}

/**
 * Import domain types (issue #25 / UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * The import flow turns a user-picked file into a `LoadedAudio` the shell
 * can draw (waveform peaks + metadata) and play (UI-004 TransportController
 * contract media source), or into a recoverable `ImportIssue` rendered with
 * the copy-deck error shape (what failed / what is kept / next action).
 */

/** Advertised container formats (GUI_UX_SPEC §3: WAV・MP3・FLAC・M4A・OGG). */
export type AudioFormat = "wav" | "mp3" | "flac" | "m4a" | "ogg";

/**
 * A user-selected audio file. Inside Tauri the native dialog and the
 * window drag-drop event hand us real filesystem paths; in plain-browser
 * dev sessions the HTML drop/file-input hands us `File` objects.
 */
export type AudioFileRef =
  | { kind: "path"; path: string; name: string }
  | { kind: "file"; file: File; name: string };

/**
 * FEAT-001 (#60): 録音由来の疑似ファイル参照。
 * `kind: "recording"` はディスク上の実ファイルではなく、メモリ上の
 * 録音バッファを表す。`mediaSource.blob` に録音結果が入るので、
 * `LoadedAudio` としては既存経路と同じ振る舞いをする。
 */
export type RecordedAudioRef = {
  kind: "recording";
  /** UI 表示用の仮想ファイル名(例: "録音_20260922_153000.wav")。 */
  name: string;
  /** "loopback" | "microphone" — どこから録ったか。 */
  source: "loopback" | "microphone";
  /** Tauri: appDataDir/recordings/ に保存済みの実ファイルパス(#70)。
   *  ある場合は内容がディスク上に永続化されており、プロジェクトの
   *  sourceAudio(originalPath/contentHash)に載せられる。 */
  path?: string;
  /** path を持つ録音の SHA-256(FND-001 の contentHash 契約)。 */
  contentHash?: string;
  /** ブラウザ dev 等、実ファイルが無い場合の録音バイト列。 */
  blob?: Blob;
};

/**
 * What the UI-004 TransportController contract can load — mirrors the
 * spike's `AudioSource` (url | blob). We always hand over a blob: either
 * the dropped `File` itself or a Blob built from `read_audio_bytes`, so the
 * user-owned source file is only ever read, never modified.
 */
export type MediaSource = { kind: "url"; url: string } | { kind: "blob"; blob: Blob };

/** Fully decoded audio ready for the AUDIO_READY state (GUI_UX_SPEC §4). */
export interface LoadedAudio {
  /** Where the bytes came from (kept for relink/re-open bookkeeping). */
  ref: AudioFileRef | RecordedAudioRef;
  fileName: string;
  format: AudioFormat;
  sizeBytes: number;
  /** Audio-clock duration in seconds (0 while unknown). */
  durationSeconds: number;
  sampleRate: number;
  /** Normalized peak amplitudes 0–1 for the waveform strip. */
  peaks: readonly number[];
  /** Playback-ready source for the transport adapter. */
  mediaSource: MediaSource;
}

/**
 * Recoverable import failures — every variant has a copy-deck title/body
 * plus a recovery action, so errors never dead-end (acceptance: "invalid
 * file has actionable Japanese error", "unsupported codec does not
 * dead-end").
 */
export type ImportIssue =
  /** Extension is not in the advertised set — honest format guidance. */
  | { kind: "unsupported"; fileName: string }
  /** Read/decode failed (corrupt file, vanished path, codec the webview
      cannot decode and FFmpeg normalization has not landed yet). */
  | { kind: "openFailed"; fileName?: string }
  /** `.hornscribe.json` could not be read or parsed. */
  | { kind: "projectOpenFailed"; fileName: string };

/**
 * The subset of `HornScribeProject` (python/hornscribe/project/model.py,
 * schema v1) the relink UX needs. `sourcePath`/`sourceHash` mirror
 * `sourceAudio.originalPath` / `contentHash`.
 */
export interface ProjectSummary {
  /** Absolute path of the .hornscribe.json file itself. */
